const v = $json;

return [{
  json: {
    origin: v.Origin,
    destination: v.Destination,
    departureDate: v['Departure Date'],
    returnDate: v['Return Date'] || '',
    adults: Number(v.Adults || 1),
    children: Number(v.Children || 0),
    infants: Number(v.Infants || 0),
    cabinClass: String(v['Cabin Class'] || 'Economy'),
    flightIndex: Math.max(0, Number(v['Flight Index'] || 0))
  }
}];

const form = $items('Normalize Flight Input', 0, 0)[0].json;

const originRaw = $items('Search Origin', 0, 0)[0].json.response?.[0]?.text || '{}';
const destinationRaw = $items('Search Destination', 0, 0)[0].json.response?.[0]?.text || '{}';

let originParsed = {};
let destinationParsed = {};

try {
  originParsed = JSON.parse(originRaw);
} catch {}

try {
  destinationParsed = JSON.parse(destinationRaw);
} catch {}

const originList = originParsed.result || originParsed.data || [];
const destinationList = destinationParsed.result || destinationParsed.data || [];

const origin = Array.isArray(originList) ? originList[0] : null;
const destination = Array.isArray(destinationList) ? destinationList[0] : null;

if (!origin) {
  throw new Error('Origin airport not found');
}

if (!destination) {
  throw new Error('Destination airport not found');
}

const originCode = origin.iata || origin.code || origin.airportCode;
const destinationCode = destination.iata || destination.code || destination.airportCode;

return [{
  json: {
    originCode,
    destinationCode,
    originData: origin,
    destinationData: destination,
    departureDate: form.departureDate,
    returnDate: form.returnDate,
    adults: form.adults,
    children: form.children,
    infants: form.infants,
    cabinClass: form.cabinClass,
    flightIndex: form.flightIndex
  }
}];

const ctx = $items('Prepare Flight Search', 0, 0)[0].json;

const raw = $json.response?.[0]?.text || '{}';

let parsed = {};

try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Invalid flight_search response JSON');
}

// Your actual response structure:
// {
//   count,
//   result: [...],
//   correlationId,
//   searchFilterObj,
//   alphaSessionId
// }

const flights =
  parsed.result ||
  parsed.data ||
  parsed.flights ||
  [];

if (!Array.isArray(flights) || flights.length === 0) {
  throw new Error('No flights found');
}

const index = Math.min(
  Number(ctx.flightIndex || 0),
  flights.length - 1
);

const selectedFlight = flights[index];

const fareSourceCode =
  selectedFlight.fareSourceCode ||
  selectedFlight.id ||
  '';

if (!fareSourceCode) {
  throw new Error('fareSourceCode missing');
}

return [
  {
    json: {
      ...ctx,

      // Session / correlation
      correlationId:
        parsed.correlationId || '',

      searchFilterObj:
        parsed.searchFilterObj || '',

      sessionId:
        parsed.alphaSessionId ||
        selectedFlight.sessionId ||
        '',

      // Selected flight
      selectedFlight,

      fareSourceCode,

      // Pricing
      searchListPrice:
        Number(
          selectedFlight.ourprice ||
          selectedFlight.totalFare ||
          selectedFlight.baseFare ||
          0
        ),

      currency:
        parsed.currency || 'USD',

      totalResults:
        parsed.count || flights.length
    }
  }
];

parameters.toolArgs:
={{
(() => {
  const search = $('Prepare Flight Search').item.json;

  const body = {
    flight: $('Prepare Flight Selection').item.json.selectedFlight,
    origin: search.originCode,
    destination: search.destinationCode,
    departureDate: search.departureDate,
    adults: search.adults,
    correlationId: $('Flight Search').item.json.response[0].text.parseJson().correlationId,
    searchFilterObj: $('Flight Search').item.json.response[0].text.parseJson().searchFilterObj,
    sessionId: $('Flight Session').item.json.response[0].text.parseJson().sessionId
  };

  if (search.returnDate) {
    body.returnDate = search.returnDate;
  }

  return JSON.stringify(body, null, 2);
})()
}}

