const paymentRaw = $json.response?.[0]?.text || '{}';
const revalidateRaw = $items('Flight Revalidate', 0, 0)[0].json.response?.[0]?.text || '{}';
const flightCtx = $items('Prepare Flight Selection', 0, 0)[0].json;

let payment = {};
let revalidated = {};

try {
  payment = JSON.parse(paymentRaw);
} catch {}

try {
  revalidated = JSON.parse(revalidateRaw);
} catch {}

return [{
  json: {
    success: true,
    origin: flightCtx.originCode,
    destination: flightCtx.destinationCode,
    departureDate: flightCtx.departureDate,
    returnDate: flightCtx.returnDate,
    flight: flightCtx.selectedFlight,
    revalidated,
    payment
  }
}];
